export function isLocalBlobUrlCurrent(
  facts: LocalBlobUrlCurrentnessFacts,
): boolean {
  if (typeof facts.mediaElementMatches !== 'boolean'
    || typeof facts.sourceUrlMatches !== 'boolean'
    || typeof facts.bindingMatches !== 'boolean') {
    throw new Error('runtime-media-local-blob-url-currentness-mismatch');
  }
  return facts.mediaElementMatches
    && facts.sourceUrlMatches
    && facts.bindingMatches;
}

export function observeLocalBlobUrlCleanup(
  facts: LocalBlobUrlCleanupFacts,
): LocalBlobUrlCleanupObservation {
  if (typeof facts.blobUrlPresent !== 'boolean'
    || typeof facts.blobUrlRevoked !== 'boolean'
    || (!facts.blobUrlPresent && facts.blobUrlRevoked)) {
    throw new Error('runtime-media-local-blob-url-cleanup-mismatch');
  }
  return {
    blobUrlPresent: facts.blobUrlPresent,
    blobUrlRevoked: facts.blobUrlRevoked,
    cleanupVerified: !facts.blobUrlPresent || facts.blobUrlRevoked,
    persistenceAuthorized: false,
    authorityGranted: false,
  };
}

export function cleanupLocalBlobUrl(
  blobUrl: string | null,
  revokeObjectUrl: (blobUrl: string) => void,
): LocalBlobUrlCleanupObservation {
  if ((blobUrl !== null && (typeof blobUrl !== 'string' || blobUrl.length === 0))
    || typeof revokeObjectUrl !== 'function') {
    throw new Error('runtime-media-local-blob-url-cleanup-input-mismatch');
  }
  let blobUrlRevoked = false;
  if (blobUrl !== null) {
    try {
      revokeObjectUrl(blobUrl);
      blobUrlRevoked = true;
    } catch {
      blobUrlRevoked = false;
    }
  }
  return observeLocalBlobUrlCleanup({
    blobUrlPresent: blobUrl !== null,
    blobUrlRevoked,
  });
}

function unavailableLocalBlobUrlCreation(): LocalBlobUrlCreationObservation {
  return {
    blobUrlCreated: false,
    blobUrl: null,
    creationVerified: false,
    persistenceAuthorized: false,
    authorityGranted: false,
  };
}

