use super::super::zero_dependency;

pub(in super::super) fn validate_relative_path(path: &str) -> Result<()> {
    if path.is_empty()
        || path.len() > 256
        || path.contains('\\')
        || path.starts_with('/')
        || path.ends_with('/')
        || path.chars().any(char::is_control)
    {
        bail!("vendored npm package path is invalid");
    }
    let components = path.split('/').collect::<Vec<_>>();
    if !(3..=8).contains(&components.len())
        || components[0] != "node_modules"
        || components
            .iter()
            .any(|part| part.is_empty() || *part == "." || *part == "..")
        || !components
            .last()
            .is_some_and(|name| name.ends_with(".js") || name.ends_with(".json"))
    {
        bail!("vendored npm package path is outside the bounded node_modules slice");
    }
    Ok(())
}

pub(super) fn validate_dependency_manifest(
    bytes: &[u8],
    name: &str,
    version: &str,
    package_type: &str,
    dependency: Option<(&str, &str)>,
) -> Result<String> {
    let value: JsonValue =
        serde_json::from_slice(bytes).context("vendored package.json is invalid")?;
    let value = value
        .as_object()
        .context("vendored package.json must be an object")?;
    zero_dependency::validate_identity(value, name, version, "vendored package.json")?;
    zero_dependency::require_text(value, "type", package_type)?;
    if let Some(expected) = dependency {
        if super::metadata::exact_one_dependency(value, "dependencies")?
            != (expected.0.to_owned(), expected.1.to_owned())
        {
            bail!("vendored package.json dependency does not match its exact lock edge");
        }
        super::metadata::reject_other_dependency_classes(value, "vendored package.json")?;
        zero_dependency::reject_non_dependency_discovery(value, "vendored package.json")?;
    } else {
        zero_dependency::reject_dependency_entries(value, "vendored package.json")?;
    }
    let main = value
        .get("main")
        .and_then(JsonValue::as_str)
        .context("vendored package.json requires a text main")?;
    super::entrypoint::validate_main(main)?;
    Ok(main.to_owned())
}

pub(super) fn validate_file_tree(
    by_path: &BTreeMap<&str, &[u8]>,
    dependencies: &[(String, String)],
) -> Result<()> {
    if by_path.keys().any(|path| {
        !dependencies
            .iter()
            .any(|(dependency_path, _main)| path.starts_with(&format!("{dependency_path}/")))
    }) {
        bail!("vendored npm package files must belong to the exact dependency closure");
    }
    for (dependency_path, main) in dependencies {
        let main_path = format!("{dependency_path}/{main}");
        if by_path
            .get(main_path.as_str())
            .is_none_or(|bytes| bytes.is_empty())
        {
            bail!("vendored npm dependency main artifact is absent or empty");
        }
    }
    Ok(())
